Section Loop.
Variable M : word -> option byte.
Variables (S p e : Z).
Variable l : list Z.
Hypothesis RO : L5.img_clear M 65536 765992.
Hypothesis HS : 140735332483168 <= S <= 2 ^ 47.
Hypothesis Hp : 0 < p.
Hypothesis He : e <= 2 ^ 47.
Hypothesis Hn : e - p <= 2 ^ 26.
Hypothesis BY : L5.bytes_at RSEGS M p l.
Hypothesis LEN : blen l = e - p.
Hypothesis LB : Forall (fun b => 0 <= b < 256) l.

(* [comment removed for export] *)
Definition goal_from (c : Z) (fx : FPState) (R : bvmap 5 word) (pc : Z) : Prop :=
  exists fx' R' v, msteps RSEGS (st fx R pc M) (st fx' R' 0x394d8 M) /\ getr R' (reg 2) = Z_to_bv 64 (S - 96) /\ (forall k, In k KL -> getr R' (reg k) = getr R (reg k))
    /\ getr R' (reg 11) = Z_to_bv 64 v /\ 0 <= v < 7 /\ (v = 0 <-> utf8_valid (skipn (Z.to_nat (c - p)) l) = true).

