Lemma slow c (IH : forall fx R c', c < c' < e -> vconst R S e -> getr R (reg 10) = Z_to_bv 64 c' -> goal_from c' fx R 0x39354) fx R d0 :
  p <= c -> c <= d0 < e -> vconst R S e -> getr R (reg 10) = Z_to_bv 64 d0 -> goal_from d0 fx R 0x393e8.
Proof.
  intros Hpc Hd V R10. pose proof V as (C2 & C5 & C6 & C7 & C8 & C9 & C12 & C13 & C14 & C15 & C16 & C17 & C18 & C19 & C20 & C21 & C22 & C28 & C29 & C30 & C31).
  destruct (byte_at d0 (d0 - p) ltac:(lia) ltac:(lia)) as (b0 & Eb0 & Hb0 & U0).
  LeanFeed.pfeed ident:(P) (PMVAUP.uvaS1_conc fx R M (fun j => match j with 2%nat => S | 33%nat => d0 | 35%nat => e - d0 | 36%nat => b0 | _ => 0 end)) ltac:(first [ PMK.sc ]).
  destruct P as (fx1 & R1 & M1 & _ & FR & _ & MS1 & KS1 & A11 & A24). assert (EM : M1 = M) by (apply functional_extensionality; exact FR). subst M1.
